import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Search","description":"Find entries in ApptiveGrid — via search and via filters.","frontmatter":{"title":"Search","description":"Find entries in ApptiveGrid — via search and via filters."},"headers":[],"relativePath":"en/grids/suche.md","filePath":"en/grids/suche.md","lastUpdated":1787319236000}'),n={name:"en/grids/suche.md"};function s(o,e,h,c,d,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h1><h2 id="search-1" tabindex="-1">Search <a class="header-anchor" href="#search-1" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>Use <strong>Search</strong> to search entries. The input field is called <em>Search for entries</em>.</p><p>With many hits, <strong>Load more ({items} of {totalItems})</strong> loads further results. With no hits, <em>No results found.</em> appears; on an error, <em>Error while searching</em>.</p><h2 id="search-or-filter" tabindex="-1">Search or filter? <a class="header-anchor" href="#search-or-filter" aria-label="Permalink to &quot;Search or filter?&quot;">​</a></h2><p>Both lead to entries, but they do different things:</p><table tabindex="0"><thead><tr><th></th><th>Search</th><th><a href="/en/ansichten/filtern-sortieren-gruppieren">Filter</a></th></tr></thead><tbody><tr><td>Purpose</td><td>Find something specific</td><td>Show a subset permanently</td></tr><tr><td>Duration</td><td>One-off</td><td>Part of the view</td></tr><tr><td>Applies to</td><td>You</td><td>everyone who sees the view</td></tr><tr><td>Precision</td><td>Free text</td><td>Condition per field</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Rule of thumb</p><p><strong>Search</strong> when you&#39;re looking for a specific entry and know its name. <strong>Filter</strong> when you regularly work with the same subset.</p><p>If you only need a subset briefly, without changing the view for others, use the temporary filter (<em>Search and filter entries (temporary)</em>).</p></div><h2 id="searching-within-a-view" tabindex="-1">Searching within a view <a class="header-anchor" href="#searching-within-a-view" aria-label="Permalink to &quot;Searching within a view&quot;">​</a></h2><p>In addition to general search, a view&#39;s toolbar has its own search function, which searches only the entries of that view — that is, within the already filtered set.</p><div class="tip custom-block"><p class="custom-block-title">Work in two stages</p><p>First narrow things down roughly with the filter, then search within the view. For large Grids, this is faster and more precise than running a free-text search over everything.</p></div><h2 id="searching-in-portals" tabindex="-1">Searching in portals <a class="header-anchor" href="#searching-in-portals" aria-label="Permalink to &quot;Searching in portals&quot;">​</a></h2><p>For a view embedded in a <a href="/en/seiten/was-sind-seiten">page</a>, the block setting <strong>Show search</strong> controls whether visitors can search. Likewise <strong>Show filter</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Turn it on for portals with many entries</p><p>A portal with a few hundred entries is barely usable for visitors without a search field. Both options cost nothing and don&#39;t change access rights — they only allow searching the data that&#39;s already visible.</p></div><p>→ <a href="/en/seiten/auswertungen">Embedding views and reports</a></p><h2 id="finding-an-entry-via-its-field" tabindex="-1">Finding an entry via its field <a class="header-anchor" href="#finding-an-entry-via-its-field" aria-label="Permalink to &quot;Finding an entry via its field&quot;">​</a></h2><p>For fields of type <strong>Link record</strong> and <strong>Link multiple records</strong>, there&#39;s a dedicated search in the picker dialog. With no hits, <em>No matching entry found.</em> appears.</p><div class="warning custom-block"><p class="custom-block-title">The target view can prevent matches</p><p>The picker dialog only shows entries from the <strong>view</strong> set for the link. If that view is filtered, entries that do exist in the Grid may be missing.</p><p>If a known entry can&#39;t be found, check the target view&#39;s filter first. → <a href="/en/grids/verknuepfungen">Linking Grids</a></p></div><h2 id="searching-spaces" tabindex="-1">Searching Spaces <a class="header-anchor" href="#searching-spaces" aria-label="Permalink to &quot;Searching Spaces&quot;">​</a></h2><p>The Space overview has its own search (<em>Search Space…</em>), which searches Space names — not their contents.</p><p>→ <a href="/en/spaces/space-anlegen">Create a Space</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li><li><a href="/en/grids/eintraege">Creating and editing entries</a></li><li><a href="/en/grids/verknuepfungen">Linking Grids</a></li></ul>',23)])])}const f=t(n,[["render",s]]);export{g as __pageData,f as default};
